import { createHash, createHmac } from 'node:crypto';

export default async function textractSignedRequest({ bucket, key, region, accessKeyId, secretAccessKey, sessionToken }, context) {
  if (typeof bucket !== 'string' || !bucket.trim() || typeof key !== 'string' || !key.trim()) throw new Error('Configure S3 bucket and object key');
  if (typeof region !== 'string' || !/^[a-z]{2}(?:-[a-z]+){1,2}-[0-9]+$/.test(region)) throw new Error('Configure a valid AWS region');
  const required = (value, name) => { if (typeof value !== 'string' || !value.trim()) throw new Error('Select the AWS ' + name + ' secret Variable'); return value.trim(); };
  const keyId = required(accessKeyId, 'access key ID'), secret = required(secretAccessKey, 'secret access key');
  if (sessionToken != null && typeof sessionToken !== 'string') throw new Error('The AWS session token must be text');
  const token = sessionToken?.trim() ?? '', service = 'textract', host = service + '.' + region + '.amazonaws.com' + (region.startsWith('cn-') ? '.cn' : '');
  const body = JSON.stringify({ Document: { S3Object: { Bucket: bucket, Name: key } } }), timestamp = new Date().toISOString().replace(/[:-]|\.\d{3}/g, ''), date = timestamp.slice(0, 8);
  const headers = { 'content-type': 'application/x-amz-json-1.1', host, 'x-amz-date': timestamp, 'x-amz-target': 'Textract.AnalyzeExpense', ...(token ? { 'x-amz-security-token': token } : {}) };
  const names = Object.keys(headers).sort(), signedHeaders = names.join(';'), canonicalHeaders = names.map(name => name + ':' + headers[name].trim().replace(/\s+/g, ' ') + '\n').join('');
  const hash = value => createHash('sha256').update(value).digest('hex'), hmac = (key, value) => createHmac('sha256', key).update(value).digest();
  const scope = date + '/' + region + '/' + service + '/aws4_request', canonical = ['POST', '/', '', canonicalHeaders, signedHeaders, hash(body)].join('\n');
  const toSign = ['AWS4-HMAC-SHA256', timestamp, scope, hash(canonical)].join('\n');
  const signingKey = hmac(hmac(hmac(hmac('AWS4' + secret, date), region), service), 'aws4_request'), signature = createHmac('sha256', signingKey).update(toSign).digest('hex');
  delete headers.host;
  headers.authorization = 'AWS4-HMAC-SHA256 Credential=' + keyId + '/' + scope + ', SignedHeaders=' + signedHeaders + ', Signature=' + signature;
  const response = await context.fetch('https://' + host + '/', {method:'POST',headers,body});
  if (!response.ok) throw new Error('Textract request failed');
  const result = await response.json();
  if (!Array.isArray(result?.ExpenseDocuments)) throw new Error('Invalid Textract response');
  const fields = {};
  for (const doc of result.ExpenseDocuments) { if (!Array.isArray(doc.SummaryFields)) throw new Error('Invalid expense fields'); for (const f of doc.SummaryFields) { const name=f?.Type?.Text||f?.LabelDetection?.Text, text=f?.ValueDetection?.Text; if(typeof name!=='string'||typeof text!=='string') throw new Error('Invalid expense field'); fields[name]=text; } }
  return {fields};
}
